+void KeyframeModel::scaleKeyframes(double scaleRatio, Fun &undo, Fun &redo)
+{
+    QWriteLocker locker(&m_lock);
+    if (qFuzzyCompare(scaleRatio, 1.0) || m_keyframeList.empty()) {
+        return;
+    }
+    std::map<GenTime, std::pair<KeyframeType::KeyframeEnum, QVariant>> oldList = m_keyframeList;
+    std::map<GenTime, std::pair<KeyframeType::KeyframeEnum, QVariant>> newList;
+    for (const auto &kf : oldList) {
+        int oldFrame = kf.first.frames(pCore->getCurrentFps());
+        int newFrame = qMax(0, int(qRound64(double(oldFrame) * scaleRatio)));
+        GenTime newPos(newFrame, pCore->getCurrentFps());
+        newList[newPos] = kf.second;
+    }
+    Fun operation = [this, newList]() {
+        QWriteLocker locker(&m_lock);
+        beginResetModel();
+        m_keyframeList = newList;
+        endResetModel();
+        sendModification();
+        Q_EMIT modelChanged();
+        return true;
+    };
+    Fun reverse = [this, oldList]() {
+        QWriteLocker locker(&m_lock);
+        beginResetModel();
+        m_keyframeList = oldList;
+        endResetModel();
+        sendModification();
+        Q_EMIT modelChanged();
+        return true;
+    };
+    operation();
+    UPDATE_UNDO_REDO_NOLOCK(operation, reverse, undo, redo);
+}
